compile.workshop:
settings
{
	main
	{
		Description: "HUD Text Crosshair | by Zezombye"
	}
	modes
	{
		Skirmish
		{
			enabled maps
			{
				Workshop Island
			}
		}
		General
		{
			Hero Limit: Off
			Respawn Time Scalar: 30%
		}
	}
}

rule ("crosshair") {
    event {
        Ongoing - Global;
    }
    actions {
        "hudSubtext(getAllPlayers(), \" \\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\", HudPosition.TOP, -999, Color.GREEN, HudReeval.VISIBILITY, SpecVisibility.NEVER)"
        Create HUD Text(All Players(All Teams), Null, Custom String(" \n"), Null, Top, -998, Null, Color(Green), Null, Visible To, Visible Never);
        Create HUD Text(All Players(All Teams), Null, Custom String(" \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n"), Null, Top, -997, Null, Color(Green), Null, Visible To, Visible Never);
        Create HUD Text(All Players(All Teams), Null, Null, Custom String("         ⊙                "), Top, -996, Null, Null, Color(Green), Visible To, Visible Never);
    }
}

rule ("disable hud") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Is Button Held(Event Player, Button(Interact)) == True;
    }
    actions {
        Disable Hero HUD(Event Player);
    }
}

rule ("enable hud") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Is Button Held(Event Player, Button(Interact)) == False;
    }
    actions {
        Enable Hero HUD(Event Player);
    }
}

